import{_ as t,o as e,c as s,a2 as a}from"./chunks/framework.uw_ZoRon.js";const d=JSON.parse('{"title":"Phase 5 — Connectivity: TCP","description":"","frontmatter":{},"headers":[],"relativePath":"phases/phase-05-tcp.md","filePath":"phases/phase-05-tcp.md"}'),h={name:"phases/phase-05-tcp.md"};function o(n,i,r,c,l,k){return e(),s("div",null,[...i[0]||(i[0]=[a('<h1 id="phase-5-—-connectivity-tcp" tabindex="-1">Phase 5 — Connectivity: TCP <a class="header-anchor" href="#phase-5-—-connectivity-tcp" aria-label="Permalink to &quot;Phase 5 — Connectivity: TCP&quot;">​</a></h1><p>A connection is just a process — Phase 5 maps TCP sockets onto the actor model, giving every connection its own isolation, supervision, and crash recovery for free.</p><h2 id="why-this-phase" tabindex="-1">Why this phase <a class="header-anchor" href="#why-this-phase" aria-label="Permalink to &quot;Why this phase&quot;">​</a></h2><p>The actor model&#39;s payoff for networking is not a clever abstraction — it&#39;s structural. Accept a socket, spawn a process to own it. That process has a mailbox, can be killed, can be supervised, and can crash without touching any other connection. The OS hands you a socket; RUSM hands you a process. Everything from Phase 3 applies immediately.</p><p>Without this, a process system is a closed universe. With it, RUSM processes speak to the outside world — and the outside world is handled with the same fault-tolerance model as everything else.</p><h2 id="what-shipped" tabindex="-1">What shipped <a class="header-anchor" href="#what-shipped" aria-label="Permalink to &quot;What shipped&quot;">​</a></h2><ol><li><strong><code>listen(addr, handler) -&gt; (SocketAddr, ProcessHandle)</code></strong> — binds a <code>TcpListener</code> and runs an acceptor process. Every accepted socket is spawned as its own process running <code>handler(ctx, stream)</code>. Returns the bound address (handy with port 0) and a handle to the acceptor — kill it to stop listening, killing the port.</li><li><strong><code>connect(addr) -&gt; io::Result&lt;TcpStream&gt;</code></strong> — opens an outbound TCP connection.</li><li><strong>Connection-storm engine</strong> (<code>rusm-bench</code>) — a ramp-and-hold load reporting real connections/sec and peak concurrency.</li></ol><h2 id="design-highlights" tabindex="-1">Design highlights <a class="header-anchor" href="#design-highlights" aria-label="Permalink to &quot;Design highlights&quot;">​</a></h2><ul><li><strong>The OS is the limit, not RUSM.</strong> RUSM mints processes far faster than any TCP stack hands out sockets. Sustained connection rate is bounded by the kernel&#39;s handshake/ephemeral-port/<code>TIME_WAIT</code> budget — the same ceiling every runtime hits. RUSM measures it honestly (~6–16k/s on loopback) rather than inflating the number.</li><li><strong><code>SO_LINGER(0)</code> to avoid <code>TIME_WAIT</code> exhaustion.</strong> An early version showed a 291/s sawtooth: client active-close piled up <code>TIME_WAIT</code> sockets. Closing with a reset via <code>socket2::SockRef</code> frees them immediately, giving a sustained rate instead of a collapsing one — a real production correctness fix.</li><li><strong>Ramp-and-hold, not flood.</strong> Flooding with parallel connectors exploded latency (the OS serializes handshakes anyway); a steady ramp measures the true ceiling. The fd limit is raised at startup via the <code>rlimit</code> crate.</li><li><strong>Kill the acceptor, kill the port.</strong> The acceptor process <em>owns</em> the <code>TcpListener</code>. Drop the handle → the process exits → the listener drops → the port closes. No separate lifecycle to manage.</li></ul><h2 id="what-this-unlocks" tabindex="-1">What this unlocks <a class="header-anchor" href="#what-this-unlocks" aria-label="Permalink to &quot;What this unlocks&quot;">​</a></h2><p>Any network protocol can be served by spawning a handler process per connection: HTTP, WebSocket, custom binary protocols. Each connection is isolated, supervised, and killable. A misbehaving client crashes its process; other connections are unaffected.</p><p>This is the direct predecessor to Phase 9&#39;s cluster transport (QUIC instead of TCP, for per-stream HoL-block freedom) and Phase 11&#39;s HTTP/WS/SSE serving model — process-per-request and process-per-connection all the way down.</p><p>This phase also completes the Wasm-free OTP core: <code>rusm-otp</code> has <strong>zero <code>wasmtime</code> dependency</strong> and stands as a fully capable actor runtime on its own.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon catppuccin-latte catppuccin-mocha vitesse-light vitesse-dark one-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D7827E;--shiki-light-font-style:inherit;--shiki-dark:#EA9A97;--shiki-dark-font-style:inherit;--shiki-catpLight:#1E66F5;--shiki-catpLight-font-style:italic;--shiki-catpDark:#89B4FA;--shiki-catpDark-font-style:italic;--shiki-vitLight:#59873A;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#80A665;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#4078F2;--shiki-oneLight-font-style:inherit;--shiki-oneDark:#61AFEF;--shiki-oneDark-font-style:inherit;">cargo</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> run</span><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#A65E2B;--shiki-vitDark:#C99076;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> -p</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> rusm-bench</span><span style="--shiki-light:#286983;--shiki-dark:#3E8FB0;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#A65E2B;--shiki-vitDark:#C99076;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> --</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> run</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> connection-storm</span><span style="--shiki-light:#D7827E;--shiki-dark:#EA9A97;--shiki-catpLight:#FE640B;--shiki-catpDark:#FAB387;--shiki-vitLight:#2F798A;--shiki-vitDark:#4C9A91;--shiki-oneLight:#986801;--shiki-oneDark:#D19A66;"> 5</span><span style="--shiki-light:#797593;--shiki-light-font-style:italic;--shiki-dark:#908CAA;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;">   #</span><span style="--shiki-light:#9893A5;--shiki-light-font-style:italic;--shiki-dark:#6E6A86;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;"> real sustained connections; watch the rate plateau</span></span></code></pre></div><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Phase complete. Connection-storm is live in the dashboard. The Wasm-free invariant holds: <code>rusm-otp</code> carries no <code>wasmtime</code> dependency.</p><hr><p><em>Next: <a href="./phase-06-wasm-backend">Phase 6</a> — Wasmtime as the process backend: swap a native Rust body for a sandboxed Wasm instance, behind the same <code>spawn()</code> call.</em></p>',19)])])}const g=t(h,[["render",o]]);export{d as __pageData,g as default};
